curl --request POST \
--url https://api.unifygtm.com/sequences/v1/sequences/{id}/pause \
--header 'x-api-key: <api-key>'
```  
```
import requests

url = "https://api.unifygtm.com/sequences/v1/sequences/{id}/pause"

headers = {"x-api-key": "<api-key>"}

response = requests.post(url, headers=headers)

print(response.text)
```  
```
const options = {method: 'POST', headers: {'x-api-key': '<api-key>'}};

fetch('https://api.unifygtm.com/sequences/v1/sequences/{id}/pause', options)
.then(res => res.json())
.then(res => console.log(res))
.catch(err => console.error(err));
```  
```
<?php

$curl = curl_init();

curl_setopt_array($curl, [
CURLOPT_URL => "https://api.unifygtm.com/sequences/v1/sequences/{id}/pause",
CURLOPT_RETURNTRANSFER => true,
CURLOPT_ENCODING => "",
CURLOPT_MAXREDIRS => 10,
CURLOPT_TIMEOUT => 30,
CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
CURLOPT_CUSTOMREQUEST => "POST",
CURLOPT_HTTPHEADER => [
"x-api-key: <api-key>"
],
]);

$response = curl_exec($curl);
$err = curl_error($curl);

curl_close($curl);

if ($err) {
echo "cURL Error #:" . $err;
} else {
echo $response;
}
```  
